insert into task_relationships(
  tenant_id,relationship_id,from_task_id,to_task_id,relationship_type,direction,reason_code,description,
  reference_visibility,idempotency_key,created_by_type,created_by_id,created_at,version
) values (
  #{relationship.tenantId},#{relationship.relationshipId},#{relationship.fromTaskId},#{relationship.toTaskId},
  #{relationship.relationshipType},#{relationship.direction},#{relationship.reasonCode},#{relationship.description},
  #{relationship.referenceVisibility},#{relationship.idempotencyKey},#{relationship.createdByType},#{relationship.createdById},
  coalesce(#{relationship.createdAt},now()),#{relationship.version}
)
on conflict (tenant_id,from_task_id,to_task_id,relationship_type) do nothing
